/* ---- Merkle ---- */
typedef struct { const alg_t *a; uint8_t dom; const uint8_t *vals; uint8_t *w; size_t n; } mk_t;
static void mk_sub(int tid, void *p) { mk_t *k = p; size_t per = k->n / NT, base = per * tid, i, m; uint8_t *w = k->w + 32 * base;
  for (i = 0; i < per; i++) h1(k->a, k->dom, k->vals + 32 * (base + i), 32, w + 32 * i);
  for (m = per; m > 1; m /= 2) for (i = 0; i < m / 2; i++) h1(k->a, k->dom, w + 64 * i, 64, w + 32 * i); }
static void merkle(mk_t *k, uint8_t *root) { size_t m, i; uint8_t top[64 * 8];
  par(mk_sub, k); for (i = 0; i < (size_t)NT; i++) memcpy(top + 32 * i, k->w + 32 * (k->n / NT) * i, 32);
  for (m = NT; m > 1; m /= 2) for (i = 0; i < m / 2; i++) h1(k->a, k->dom, top + 64 * i, 64, top + 32 * i); memcpy(root, top, 32); }
static int merkle_bench(int reps, const char *ks) { const char *p = ks; double *t = malloc(sizeof(double) * (reps + 2));
  while (*p) { int k = atoi(p), mi, r; size_t n = (size_t)1 << k, i; uint64_t x = 0x4D45524B4C450000ULL + (uint64_t)k; uint8_t *vals = malloc(32 * n), *w = malloc(32 * n), root[32]; char st[300], h[70];
    for (i = 0; i < 32 * n; i++) vals[i] = rng_byte(&x);
    for (mi = 0; mi < 3; mi++) { const alg_t *A[3] = {&MINI128, &TURBO128, &SHAKE128}; uint8_t D[3] = {0x01, 0x1F, 0x1F}; const char *nm[3] = {"minishake128", "turboshake128", "shake128"};
      mk_t mk = {A[mi], D[mi], vals, w, n};
      for (r = 0; r < reps + 2; r++) { double t0 = now_ns(); merkle(&mk, root); t[r] = now_ns() - t0; }
      pstats(st, t + 2, reps); hex(h, root, 32); qsort(t + 2, reps, sizeof *t, cmpd);
      printf("RESULT swmerkle k=%d alg=%s threads=%d hashes=%zu %s Mhash_per_s=%.4f root=%s\n", k, nm[mi], NT, 2 * n - 1, st, (2 * n - 1) / t[2 + reps / 2] * 1e3, h); }
    free(vals); free(w); while (*p && *p != ',') p++; if (*p) p++; }
  return 0; }
int main(int argc, char **argv) {
  if (argc >= 2 && !strcmp(argv[1], "vectors")) { pool(argc >= 3 ? atoi(argv[2]) : 1); return vectors(); }
  if (argc >= 4 && !strcmp(argv[1], "kt")) { pool(atoi(argv[3])); return kt_bench(atoi(argv[2])); }
  if (argc >= 5 && !strcmp(argv[1], "merkle")) { pool(atoi(argv[3])); return merkle_bench(atoi(argv[2]), argv[4]); }
  fprintf(stderr, "usage: modes_bench vectors [threads] | kt <reps> <threads> | merkle <reps> <threads> <k,k,...>\n"); return 2; }
